if (!root) {
    root = new TreeNode();
    root->value = item;
    root->left = nullptr;
    root->right = nullptr;
    root->bFactor = 0;
} else {
    if (item < root->value) {
        avlInsert(root->left, item);
    } else if (item > root->value) {
        avlInsert(root->right, item);
    } else {
        return; // Item already exists
    }
}

auto getHeight = [](auto self, TreeNode* node) -> int {
    return node ? 1 + ( (self(self, node->left) > self(self, node->right)) ? self(self, node->left) : self(self, node->right) ) : 0;
};

auto getBalance = [&](TreeNode* node) {
    return node ? getHeight(getHeight, node->left) - getHeight(getHeight, node->right) : 0;
};

root->bFactor = getBalance(root);

if (root->bFactor > 1) {
    if (getBalance(root->left) >= 0) {
        // Right rotation
        TreeNode* k2 = root->left;
        root->left = k2->right;
        k2->right = root;
        root = k2;
    } else {
        // Left-Right rotation
        TreeNode* k1 = root->left;
        TreeNode* k2 = k1->right;
        k1->right = k2->left;
        k2->left = k1;
        root->left = k2;

        TreeNode* k3 = root;
        TreeNode* k4 = k3->left;
        k3->left = k4->right;
        k4->right = k3;
        root = k4;
    }
} else if (root->bFactor < -1) {
    if (getBalance(root->right) <= 0) {
        // Left rotation
        TreeNode* k2 = root->right;
        root->right = k2->left;
        k2->left = root;
        root = k2;
    } else {
        // Right-Left rotation
        TreeNode* k1 = root->right;
        TreeNode* k2 = k1->left;
        k1->left = k2->right;
        k2->right = k1;
        root->right = k2;

        TreeNode* k3 = root;
        TreeNode* k4 = k3->right;
        k3->right = k4->left;
        k4->left = k3;
        root = k4;
    }
}

if (root) {
    root->bFactor = getBalance(root);
}

